package com.nattechnologies.trastcms.plugins.pay.cleanpay;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.slf4j.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.math.*;import java.net.URI;import java.time.*;import java.util.*;
@Service public class CleanPayClient{private static final Logger log=LoggerFactory.getLogger(CleanPayClient.class);private final CleanPaySettingsRepository repo;private final CleanPaySecretCodec secrets;private final ObjectMapper mapper;private final Map<String,Object> profile;private final RestClient client=RestClient.create();public CleanPayClient(CleanPaySettingsRepository r,CleanPaySecretCodec s,ObjectMapper m){repo=r;secrets=s;mapper=m;Map<String,Object> loaded=Map.of();try(var in=getClass().getResourceAsStream("/cleanpay/promerica-profile.json")){if(in!=null)loaded=m.readValue(in,new TypeReference<Map<String,Object>>(){});}catch(Exception ignored){}profile=loaded;}
public CleanPaySettings settings(){return repo.findFirstByOrderByIdAsc().orElseGet(()->{CleanPaySettings value=new CleanPaySettings();value.setApiUrl(stringProfile("paymentUrl"));value.setStatusUrl(stringProfile("statusUrl"));value.setAuthHeader(Optional.ofNullable(stringProfile("authHeader")).filter(x->!x.isBlank()).orElse("Authorization"));value.setAuthScheme(Optional.ofNullable(stringProfile("authScheme")).orElse("Bearer"));return value;});}private String stringProfile(String key){Object value=profile.get(key);return value==null?null:String.valueOf(value);}
public CleanPaySettings save(CleanPaySettings input,String token){CleanPaySettings s=repo.findFirstByOrderByIdAsc().orElseGet(CleanPaySettings::new);s.setEnabled(input.isEnabled());s.setApiUrl(input.getApiUrl());s.setStatusUrl(input.getStatusUrl());s.setMerchantId(input.getMerchantId());s.setTerminalId(input.getTerminalId());s.setAuthHeader(input.getAuthHeader());s.setAuthScheme(input.getAuthScheme());s.setThreeDsEnabled(input.isThreeDsEnabled());s.setReturnUrl(input.getReturnUrl());s.setCancelUrl(input.getCancelUrl());s.setTimeoutSeconds(input.getTimeoutSeconds());s.setAdditionalJson(input.getAdditionalJson());if(token!=null&&!token.isBlank())s.setTokenEncrypted(secrets.encrypt(token.trim()));return repo.save(s);}
public GatewayResponse charge(Map<String,Object> input){CleanPaySettings s=settings();if(!s.isEnabled())return GatewayResponse.failure("CLEANPAY_DISABLED","CleanPay is disabled",null);if(s.getApiUrl()==null||s.getApiUrl().isBlank())return GatewayResponse.failure("CLEANPAY_URL_MISSING","CleanPay API URL is not configured",null);String token=secrets.decrypt(s.getTokenEncrypted());if(token==null||token.isBlank())return GatewayResponse.failure("CLEANPAY_TOKEN_MISSING","CleanPay token is not configured",null);
 Map<String,Object> payload=payload(input,s);try{Map<String,Object> response=client.post().uri(URI.create(s.getApiUrl())).header(s.getAuthHeader()==null?"Authorization":s.getAuthHeader(),((s.getAuthScheme()==null?"":s.getAuthScheme().trim()+" ")+token).trim()).contentType(MediaType.APPLICATION_JSON).accept(MediaType.APPLICATION_JSON).body(payload).retrieve().body(new org.springframework.core.ParameterizedTypeReference<Map<String,Object>>(){});return map(response);}catch(Exception ex){String msg=sanitize(ex.getMessage());log.warn("CleanPay request failed: {}",msg);return GatewayResponse.failure("CLEANPAY_HTTP_ERROR",msg,null);}}
private Map<String,Object> payload(Map<String,Object> in,CleanPaySettings s){Object documented=profile.get("requestTemplate");Map<String,Object> values=new LinkedHashMap<>(in);values.put("merchantId",s.getMerchantId());values.put("terminalId",s.getTerminalId());values.put("threeDsEnabled",s.isThreeDsEnabled());values.put("returnUrl",s.getReturnUrl());values.put("cancelUrl",s.getCancelUrl());Object resolved=resolveTemplate(documented,values);Map<String,Object> out=resolved instanceof Map<?,?> m?new LinkedHashMap<>((Map<String,Object>)m):new LinkedHashMap<>();if(out.isEmpty()){out.put("merchantId",s.getMerchantId());out.put("terminalId",s.getTerminalId());copy(in,out,"orderId","reference","amount","currency","description","customerName","customerEmail","customerPhone","cardNumber","expirationMonth","expirationYear","cvv");Map<String,Object> three=new LinkedHashMap<>();three.put("enabled",s.isThreeDsEnabled());three.put("returnUrl",s.getReturnUrl());three.put("cancelUrl",s.getCancelUrl());out.put("threeDS",three);}if(s.getAdditionalJson()!=null&&!s.getAdditionalJson().isBlank())try{out.putAll(mapper.readValue(s.getAdditionalJson(),new TypeReference<Map<String,Object>>(){}));}catch(Exception e){throw new IllegalArgumentException("Additional CleanPay JSON is invalid");}return out;}private Object resolveTemplate(Object value,Map<String,Object> values){if(value instanceof Map<?,?> m){Map<String,Object> out=new LinkedHashMap<>();m.forEach((k,v)->out.put(String.valueOf(k),resolveTemplate(v,values)));return out;}if(value instanceof List<?> l)return l.stream().map(v->resolveTemplate(v,values)).toList();if(value instanceof String text&&text.startsWith("{{")&&text.endsWith("}}")){String key=text.substring(2,text.length()-2);return values.get(key);}return value;}
private void copy(Map<String,Object> in,Map<String,Object> out,String...keys){for(String k:keys)if(in.containsKey(k)&&in.get(k)!=null)out.put(k,in.get(k));}
@SuppressWarnings("unchecked")private GatewayResponse map(Map<String,Object> r){if(r==null)return GatewayResponse.failure("CLEANPAY_EMPTY_RESPONSE","CleanPay returned an empty response",null);String status=find(r,"status","state","result","responseCode","code");String id=find(r,"transactionId","transaction_id","id","reference","authorizationCode");String message=find(r,"message","description","error","responseMessage");String redirect=findDeep(r,"redirectUrl","redirect_url","challengeUrl","challenge_url","acsUrl","acs_url","threeDSUrl","url");String html=findDeep(r,"challengeHtml","html","form","threeDSHtml");boolean action=redirect!=null||html!=null||contains(status,"3ds","challenge","pending","authentication_required","requires_action");boolean ok=contains(status,"approved","success","authorized","00","completed")&&!action;if(action)return new GatewayResponse(false,true,id,status,message,redirect,html,sanitizeMap(r));if(ok)return new GatewayResponse(true,false,id,status,message,null,null,sanitizeMap(r));return GatewayResponse.failure(status==null?"CLEANPAY_DECLINED":status,message==null?"Payment was not approved":message,sanitizeMap(r));}
private boolean contains(String value,String...tokens){if(value==null)return false;String v=value.toLowerCase();return Arrays.stream(tokens).anyMatch(v::contains);}private String find(Map<String,Object> m,String...keys){for(String k:keys)for(var e:m.entrySet())if(e.getKey().equalsIgnoreCase(k)&&e.getValue()!=null)return String.valueOf(e.getValue());return null;}private String findDeep(Object value,String...keys){if(value instanceof Map<?,?> m){for(var e:m.entrySet())for(String k:keys)if(String.valueOf(e.getKey()).equalsIgnoreCase(k)&&e.getValue()!=null)return String.valueOf(e.getValue());for(Object v:m.values()){String found=findDeep(v,keys);if(found!=null)return found;}}if(value instanceof Collection<?> c)for(Object v:c){String f=findDeep(v,keys);if(f!=null)return f;}return null;}
private Map<String,Object> sanitizeMap(Map<String,Object> m){Map<String,Object> out=new LinkedHashMap<>();m.forEach((k,v)->{String key=k.toLowerCase();out.put(k,key.contains("token")||key.contains("card")||key.contains("cvv")||key.contains("pan")?"[redacted]":v);});return out;}private String sanitize(String s){if(s==null)return "Unknown CleanPay error";return s.replaceAll("(?i)(bearer|token|authorization|cvv|pan|card)[=: ]+[^ ,;]+","$1=[redacted]");}
public record GatewayResponse(boolean approved,boolean requiresAction,String transactionId,String status,String message,String redirectUrl,String challengeHtml,Map<String,Object> raw){static GatewayResponse failure(String status,String message,Map<String,Object> raw){return new GatewayResponse(false,false,null,status,message,null,null,raw);}}
}
